python3 -c "
import json

with open('/app/output/solution.json','r') as f:
    data = json.load(f)

# 1. Verify JSON structure
r0 = data['records'][0]
print('Schema check:')
print(f'  Top keys: {list(data.keys())}')
print(f'  Record keys: {list(r0.keys())}')
print(f'  Normalized keys: {list(r0[\"normalized\"][0].keys())}')
print(f'  Total records: {len(data[\"records\"])}')
print()

# 2. Check all record_ids are present
ids = set(r['record_id'] for r in data['records'])
expected = set(f'R{i:07d}' for i in range(1, 12001))
missing = expected - ids
extra = ids - expected
print(f'Missing IDs: {len(missing)}')
print(f'Extra IDs: {len(extra)}')
print()

# 3. Check segment_id format
bad_seg = 0
for r in data['records']:
    for s in r['normalized']:
        if not s['segment_id'].startswith(r['record_id'] + '-S'):
            bad_seg += 1
        seg_num = s['segment_id'].split('-S')[-1]
        if not seg_num.isdigit() or int(seg_num) < 1:
            bad_seg += 1
print(f'Bad segment_ids: {bad_seg}')

# 4. Check span_text is in raw_reason_text
bad_span = 0
bad_span_examples = []
for r in data['records']:
    for s in r['normalized']:
        if s['span_text'] not in r['raw_reason_text']:
            bad_span += 1
            if len(bad_span_examples) < 5:
                bad_span_examples.append((r['record_id'], s['span_text'][:50], r['raw_reason_text'][:50]))
print(f'Spans not in raw text: {bad_span}')
if bad_span_examples:
    for ex in bad_span_examples:
        print(f'  {ex[0]}: span=\"{ex[1]}\" raw=\"{ex[2]}\"')
print()

# 5. Check pred_code and pred_label validity
import csv
valid_codes = {}
for fn in ['codebook_P1_POWER.csv','codebook_P2_CTRL.csv','codebook_P3_RF.csv']:
    with open(f'/app/data/{fn}','r') as f:
        reader = csv.DictReader(f)
        for row in reader:
            valid_codes[row['code'].strip()] = row['standard_label'].strip()

bad_code = 0
bad_label = 0
for r in data['records']:
    for s in r['normalized']:
        if s['pred_code'] != 'UNKNOWN':
            if s['pred_code'] not in valid_codes:
                bad_code += 1
            elif valid_codes[s['pred_code']] != s['pred_label']:
                bad_label += 1
        else:
            if s['pred_label'] != '':
                bad_label += 1

print(f'Invalid codes (not in codebook): {bad_code}')
print(f'Label mismatches: {bad_label}')
print()

# 6. Check confidence range
bad_conf = 0
unknown_higher = 0
for r in data['records']:
    for s in r['normalized']:
        if not (0.0 <= s['confidence'] <= 1.0):
            bad_conf += 1
        if s['pred_code'] == 'UNKNOWN' and s['confidence'] > 0.35:
            unknown_higher += 1
print(f'Confidence out of [0,1]: {bad_conf}')
print(f'UNKNOWN with conf > 0.35: {unknown_higher}')
print()

# 7. Product-code alignment check
bad_product = 0
for r in data['records']:
    for s in r['normalized']:
        if s['pred_code'] != 'UNKNOWN':
            if not s['pred_code'].startswith(r['product_id']):
                bad_product += 1
print(f'Code-product misalignment: {bad_product}')
" 2>&1
